import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
top_n = target.top_n


def test_basic_descending():
    # 3 largest of [1,2,3,4,5] in descending order
    assert top_n([1, 2, 3, 4, 5], 3) == [5, 4, 3]


def test_descending_unsorted_input():
    assert top_n([10, 1, 7, 3, 9], 2) == [10, 9]


def test_duplicates_preserved():
    assert top_n([5, 5, 1, 3], 3) == [5, 5, 3]


def test_n_zero_empty():
    assert top_n([4, 2, 8], 0) == []


def test_n_larger_than_input_all_descending():
    assert top_n([2, 9, 4], 5) == [9, 4, 2]


def test_n_equals_size():
    assert top_n([1, 3, 2], 3) == [3, 2, 1]


def test_single_element():
    assert top_n([7], 1) == [7]


def test_negative_values():
    assert top_n([-1, -5, -3], 2) == [-1, -3]

