import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
is_strong_password = target.is_strong_password


def test_all_requirements_met():
    assert is_strong_password("Abcdef1!") is True


def test_exactly_eight_chars_ok():
    assert len("Abcdef1!") == 8
    assert is_strong_password("Abcdef1!") is True


def test_longer_than_eight_ok():
    assert is_strong_password("Abcdefgh1!xyz") is True


def test_too_short_seven():
    assert is_strong_password("Abcde1!") is False


def test_empty():
    assert is_strong_password("") is False


def test_missing_upper():
    assert is_strong_password("abcdef1!") is False


def test_missing_lower():
    assert is_strong_password("ABCDEF1!") is False


def test_missing_digit():
    assert is_strong_password("Abcdefg!") is False


def test_missing_symbol():
    assert is_strong_password("Abcdefg1") is False


def test_symbol_underscore():
    assert is_strong_password("Abcdef1_") is True


def test_non_string_raises_typeerror():
    try:
        is_strong_password(12345678)
    except TypeError:
        return
    raise AssertionError("expected TypeError for non-string input")

