import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
calculate_cart_total = target.calculate_cart_total


def test_no_tax_sum():
    assert calculate_cart_total([1.0, 2.0, 3.0], 0.0) == 6.0


def test_single_price_no_tax():
    assert calculate_cart_total([5.0], 0.0) == 5.0


def test_empty_cart_returns_zero():
    assert calculate_cart_total([], 0.05) == 0.0


def test_empty_cart_zero_tax():
    assert calculate_cart_total([], 0.0) == 0.0


def test_ten_percent_tax():
    assert calculate_cart_total([10.0, 5.0], 0.10) == 16.5


def test_rounds_to_two_decimals():
    # 10 * 1.0825 = 10.825 -> rounds to 10.83
    assert calculate_cart_total([10.0], 0.0825) == 10.83


def test_rounds_up_cents():
    # 1.0 * 1.005 = 1.005 -> two decimals
    result = calculate_cart_total([1.0], 0.005)
    assert abs(result - 1.0) < 0.02


def test_integer_inputs_accepted():
    assert calculate_cart_total([2, 3], 0) == 5.0


def test_negative_price_raises_valueerror():
    try:
        calculate_cart_total([-1.0], 0.0)
    except ValueError:
        return
    raise AssertionError("expected ValueError for negative price")


def test_negative_tax_raises_valueerror():
    try:
        calculate_cart_total([1.0], -0.1)
    except ValueError:
        return
    raise AssertionError("expected ValueError for negative tax rate")


def test_non_numeric_price_raises_typeerror():
    try:
        calculate_cart_total(["a"], 0.0)
    except TypeError:
        return
    raise AssertionError("expected TypeError for non-numeric price")


def test_non_numeric_tax_raises_typeerror():
    try:
        calculate_cart_total([1.0], "x")
    except TypeError:
        return
    raise AssertionError("expected TypeError for non-numeric tax rate")

