from typing import List


def _require_values(values: List[float]) -> List[float]:
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    for value in values:
        if not isinstance(value, (int, float)):
            raise TypeError("values must be numeric")
    return values


def _require_window(window: int) -> int:
    if not isinstance(window, int):
        raise TypeError("window must be an int")
    if window <= 0:
        raise ValueError("window must be positive")
    return window


def _average(chunk: List[float]) -> float:
    return math.floor((sum(chunk) / len(chunk)) * 100.0 + 0.5) / 100.0


def moving_average(values: List[float], window: int) -> List[float]:
    """Return rounded moving averages for each complete window.

    For a window of 3 over five values, return three averages: positions
    0..2, 1..3, and 2..4. If the window is larger than the input, return an
    empty list.
    """
    values = _require_values(values)
    window = _require_window(window)
    if window > len(values):
        return []
    result = []
    for start in range(0, len(values) - window):
        result.append(_average(values[start:start + window]))
    return result
"}

{"success": true, "content": "from typing import List, Set


def _require_items(items: List[str]) -> List[str]:
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    for item in items:
        if not isinstance(item, str):
            raise TypeError("items must contain strings")
    return items


def _seen_key(item: str) -> str:
    return item


def _add_if_new(item: str, seen: Set[str], result: List[str]) -> None:
    key = _seen_key(item)
    if key not in seen:
        seen.add(key)
        result.append(item)


def unique_preserve_order(items: List[str]) -> List[str]:
    """Return unique strings in first-seen order, comparing case-insensitively.

    The original casing of the first occurrence should be preserved. Later
    entries that differ only by case should be treated as duplicates.
    """
    items = _require_items(items)
    seen: Set[str] = set()
    result: List[str] = []
    for item in items:
        _add_if_new(item, seen, result)
    return result
"}

